from functools import lru_cache
from itertools import combinations_with_replacement

PRICES = {1:800, 2:1520, 3:2160, 4:2560, 5:3000}
MASKS = list(range(1, 32))

@lru_cache(None)
def exact(state):
    state = tuple(sorted(state, reverse=True))
    if not any(state):
        return 0
    best = None
    for mask in MASKS:
        nxt = list(state)
        for i in range(5):
            if mask & (1 << i):
                if nxt[i] == 0:
                    break
                nxt[i] -= 1
        else:
            val = PRICES[mask.bit_count()] + exact(tuple(sorted(nxt, reverse=True)))
            if best is None or val < best:
                best = val
    return best

def formula(state):
    a,b,c,d,e = sorted(state, reverse=True)
    g5, g4, g3, g2, g1 = e, d-e, c-d, b-c, a-b
    k = min(g5, g3)
    g5 -= k; g3 -= k; g4 += 2*k
    return g5*3000 + g4*2560 + g3*2160 + g2*1520 + g1*800

limit = 20
states = list(combinations_with_replacement(range(limit+1), 5))
bad = [(s, exact(s), formula(s)) for s in states if exact(s) != formula(s)]
print(f'checked {len(states)} sorted count vectors through count {limit}; mismatches={len(bad)}')
print(bad[:10])
print('cache size:', exact.cache_info().currsize)
